            for item in target:
                scope[glom](item, item_spec, scope)
            return target
        if isinstance(spec, list):
            if len(spec) == 0:
                if len(target) != 0:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise ValueError("list specs must have exactly one element")
            result = []
            for item in target:
                result.append(scope[glom](item, spec[0], scope))
            return result
        if isinstance(spec, tuple):
            if len(spec) != len(target):
                raise MatchError("{0!r} does not match {1!r}", target, spec)
            result = []
            for t, s in zip(target, spec):
                result.append(scope[glom](t, s, scope))
            return type(spec)(result)
    elif callable(spec):
        try:
            if not spec(target):
                raise MatchError("{0!r} did not satisfy {1!r}", target, spec)
        except MatchError:
            raise
        except Exception as e:
            raise MatchError("{0!r} did not satisfy {1!r}", target, spec)
        return target
    else:
        if target != spec:
            raise MatchError("{0!r} does not match {1!r}", target, spec)
        return target
